const RESULTS_COLLECTION = "results";
const resultsCol = collection(db, RESULTS_COLLECTION);

/**
 * Add a quiz result to Firestore
 * Always writes `submittedAt` using server time (authoritative).
 * Also writes `createdAt` for redundancy.
 */
export async function addResult(result = {}) {
  const payload = {
    ...result,
    submittedAt: serverTimestamp(),
    createdAt: serverTimestamp(),
  };
  return await addDoc(resultsCol, payload);
}

/**
 * Subscribe to results collection snapshot (real-time)
 * Ordered by score desc, then earliest submitted first (tie-breaker),
 * and finally createdAt as a tertiary fallback.
 */
export function onResultsSnapshot(cb, onError) {
  const q = query(
    resultsCol,
    orderBy("score", "desc"),
    orderBy("submittedAt", "asc"),
    orderBy("createdAt", "asc")
  );
  const unsub = onSnapshot(
    q,
    (snapshot) => { if (typeof cb === "function") cb(snapshot); },
    (err) => { console.error("onResultsSnapshot error:", err); if (typeof onError === "function") onError(err); }
  );
  return unsub;
}

/**
 * Get all results once (no realtime) using the same ordering
 */
export async function getAllResultsOnce() {
  const qy = query(
    resultsCol,
    orderBy("score", "desc"),
    orderBy("submittedAt", "asc"),
    orderBy("createdAt", "asc")
  );
  const snap = await getDocs(qy);
  const arr = [];
  snap.forEach((d) => arr.push({ id: d.id, ...d.data() }));
  return arr;
}

/**
 * Clear all documents in the results collection (batched deletes)
 */
export async function clearAllResults() {
  const BATCH_SIZE = 400;

  async function deleteBatch() {
    const qy = query(resultsCol, limit(BATCH_SIZE));
    const snap = await getDocs(qy);
    if (snap.empty) return 0;

    const batch = writeBatch(db);
    snap.forEach((d) => batch.delete(doc(db, RESULTS_COLLECTION, d.id)));
    await batch.commit();
    return snap.size;
  }

  let totalDeleted = 0;
  for (let i = 0; i < 100; i++) {
    const deleted = await deleteBatch();
    totalDeleted += deleted;
    if (deleted < BATCH_SIZE) break;
  }
  return { deleted: totalDeleted };
}

/* ===============================
   Quiz settings & schedule helpers
   Stored at document: settings/quiz
   Fields: active (boolean), auto (boolean), startAt (Timestamp), endAt (Timestamp), updatedAt, updatedBy
   =============================== */

export async function setQuizSettings(settings = {}) {
  try {
    const ref = doc(db, "settings", "quiz");
    const payload = { ...settings, updatedAt: serverTimestamp() };
    await setDoc(ref, payload, { merge: true });
    return true;
  } catch (err) {
    console.error("setQuizSettings error:", err);
    throw err;
  }
}

export async function setQuizActive(flag, by = null) {
  try {
    return await setQuizSettings({ active: !!flag, updatedBy: by || null });
  } catch (err) {
    console.error("setQuizActive error:", err);
    throw err;
  }
}

export function onQuizSettingsSnapshot(cb, onError) {
  const ref = doc(db, "settings", "quiz");
  const unsub = onSnapshot(
    ref,
    (snap) => {
      if (!snap.exists()) {
        if (typeof cb === "function")
          cb({ active: false, auto: false, startAt: null, endAt: null, updatedAt: null, updatedBy: null });
        return;
      }
      const data = snap.data();
      if (typeof cb === "function")
        cb({
          active: !!data.active,
          auto: !!data.auto,
          startAt: data.startAt || null,
          endAt: data.endAt || null,
          updatedAt: data.updatedAt || null,
          updatedBy: data.updatedBy || null
        });
    },
    (err) => {
      console.error("onQuizSettingsSnapshot error:", err);
      if (typeof onError === "function") onError(err);
    }
  );
  return unsub;
}

