const loadQuizActive = () => { try { return localStorage.getItem("quizActive") === "true"; } catch { return false; } };
const saveQuizActiveFlag = (val) => { try { localStorage.setItem("quizActive", val ? "true" : "false") } catch (e) { console.warn(e); } };

function tsToInputValue(ts) {
  try {
    if (!ts) return "";
    const d = typeof ts.toDate === "function" ? ts.toDate() : new Date(ts);
    const pad = (n) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  } catch { return ""; }
}
function parseInputValueToDate(val){ if(!val) return null; const d=new Date(val); return isNaN(+d)?null:d; }
function msToHMS(ms){ if(ms<=0) return "00:00:00"; const s=Math.floor(ms/1000); const h=Math.floor((s%86400)/3600); const m=Math.floor((s%3600)/60); const ss=s%60; const pad=n=>String(n).padStart(2,"0"); return `${pad(h)}:${pad(m)}:${pad(ss)}`; }
function fmtDateTimeLocal(x){
  try{
    if(!x) return "";
    const d = typeof x.toDate === "function" ? x.toDate() : (x instanceof Date ? x : new Date(x));
    if (isNaN(+d)) return "";
    return d.toLocaleString();
  }catch{ return ""; }
}

/* ---------------- Leaderboard ---------------- */
function Leaderboard({ results }){
  const safe = Array.isArray(results) ? results : [];

  const ts = (t) => {
    if (!t) return Number.POSITIVE_INFINITY;
    if (typeof t.toDate === "function") return t.toDate().getTime();
    const d = t instanceof Date ? t : new Date(t);
    return isNaN(+d) ? Number.POSITIVE_INFINITY : d.getTime();
  };

  const sorted = safe.slice().sort((a, b) => {
    const sa = a.score || 0;
    const sb = b.score || 0;
    if (sb !== sa) return sb - sa;
    const ta = ts(a.submittedAt) || ts(a.createdAt);
    const tb = ts(b.submittedAt) || ts(b.createdAt);
    return ta - tb;
  });
  const total = sorted.length;

  return (
    <div style={{ marginTop:24, background:'#fff', padding:16, borderRadius:8, border:'1px solid #e5e7eb' }}>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
        <h2 style={{ margin:0 }}>Leaderboard</h2>
        <div style={{ color:'red', fontSize:14, fontWeight:'bold' }}>Total participants: {total}</div>
      </div>
      <table style={{ width:'100%', borderCollapse:'collapse' }}>
        <thead>
          <tr style={{ background:'#f3f4f6' }}>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>S.No</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Full Name</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Designation</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Office</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Mobile</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Unit</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Score</th>
            <th style={{ padding:8, border:'1px solid #e6edf3' }}>Submitted At</th>
          </tr>
        </thead>
        <tbody>
          {sorted.length===0? (
            <tr><td colSpan="8" style={{ textAlign:'center', padding:16 }}>No results yet</td></tr>
          ): sorted.map((r,i)=> (
            <tr key={r.id||i}>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{i+1}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{r.name}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{r.designation}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{r.office}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{r.mobile||''}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{r.unit}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{r.score}</td>
              <td style={{ padding:8, border:'1px solid #eef2f7' }}>{fmtDateTimeLocal(r.submittedAt || r.createdAt)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* ---------------- Admin Panel ---------------- */
function AdminPanel({ results, onLogout, allowRetake, quizSettings, onSaveSchedule }){
  const safeR = Array.isArray(results)?results:[];
  const [startInput,setStartInput]=useState(tsToInputValue(quizSettings.startAt));
  const [endInput,setEndInput]=useState(tsToInputValue(quizSettings.endAt));
  const [autoEnabled,setAutoEnabled]=useState(!!quizSettings.auto);

  useEffect(()=>{ 
    setStartInput(tsToInputValue(quizSettings.startAt)); 
    setEndInput(tsToInputValue(quizSettings.endAt)); 
    setAutoEnabled(!!quizSettings.auto); 
  },[quizSettings.startAt, quizSettings.endAt, quizSettings.auto]);

  const saveSchedule = async()=>{
    const start=parseInputValueToDate(startInput); 
    const end=parseInputValueToDate(endInput);
    if(startInput && !start) return alert('Invalid start date/time');
    if(endInput && !end) return alert('Invalid end date/time');
    if(start && end && end<=start) return alert('End time must be after start time');
    if(!window.confirm('Save schedule?')) return;
    try{ 
      await onSaveSchedule({ auto:!!autoEnabled, startAt:start, endAt:end }); 
      alert('Schedule saved.'); 
    }catch(e){ 
      console.error(e); 
      alert('Failed to save schedule.'); 
    }
  };

  const exportCSVLocal=()=>{
    if(!safeR.length) return alert('No results to export');

    const ts = (t) => {
      if (!t) return Number.POSITIVE_INFINITY;
      if (typeof t.toDate === "function") return t.toDate().getTime();
      const d = t instanceof Date ? t : new Date(t);
      return isNaN(+d) ? Number.POSITIVE_INFINITY : d.getTime();
    };

    const header=['Full Name','Designation','Office','Mobile','Unit','Score','Submitted At'];

    const sorted = safeR.slice().sort((a, b) => {
      const sa = a.score || 0;
      const sb = b.score || 0;
      if (sb !== sa) return sb - sa;
      const ta = ts(a.submittedAt) || ts(a.createdAt);
      const tb = ts(b.submittedAt) || ts(b.createdAt);
      return ta - tb;
    });

    const rows=sorted.map(r=>[
      r.name||'',r.designation||'',r.office||'',r.mobile||'',r.unit||'',r.score||0, fmtDateTimeLocal(r.submittedAt || r.createdAt)
    ]);
    const csv=[header,...rows].map(row=>row.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n');
    const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}); 
    const url=URL.createObjectURL(blob); 
    const a=document.createElement('a'); 
    a.href=url; 
    a.download=`quiz-leaderboard-${new Date().toISOString().slice(0,10)}.csv`; 
    document.body.appendChild(a); 
    a.click(); 
    a.remove(); 
    URL.revokeObjectURL(url);
  };

  const clearLeaderboardHandler=async()=>{ 
    if(!window.confirm('Clear all leaderboard results?')) return;
    try{ 
      await clearAllResults(); 
      alert('Leaderboard cleared.'); 
    }catch(e){ 
      console.error(e); 
      alert('Failed to clear leaderboard'); 
    } 
  };

  const allowedUnits=new Set(['Hubballi Division','Mysore Division','Bangalore Division','Hubballi Workshop','Mysore Workshop','Headquarters','Construction','Others']);
  const unitCounts=safeR.reduce((acc,r)=>{ const raw=(r.unit||'').trim(); const u=(raw&&allowedUnits.has(raw))?raw:'Others'; acc[u]=(acc[u]||0)+1; return acc; },{});
  const unitLabels=Object.keys(unitCounts).sort((a,b)=>a.localeCompare(b));
  const total=unitLabels.reduce((s,u)=>s+(unitCounts[u]||0),0);

  return (
    <div style={{ maxWidth:980, margin:'24px auto', padding:18, width:'100%', boxSizing:'border-box' }}>
      <div style={{ background:'#fff', padding:16, borderRadius:8, border:'1px solid #e5e7eb' }}>
        <h2>Admin Panel</h2>
        <div style={{ marginBottom:14, display:'flex', gap:12, alignItems:'center', flexWrap:'wrap' }}>
          <div>
            <strong>Quiz Automation Status:</strong>
            <div style={{ fontWeight:700, color: quizSettings.auto ? '#065f46' : '#991b1b' }}>{quizSettings.auto?'Enabled':'Disabled'}</div>
            <div style={{ fontSize:12, color:'#6b7280' }}>Scheduled window: {quizSettings.startAt?tsToInputValue(quizSettings.startAt).replace('T',' '):'—'} to {quizSettings.endAt?tsToInputValue(quizSettings.endAt).replace('T',' '):'—'}</div>
          </div>
          <div style={{ marginLeft:'auto', display:'flex', gap:8, flexWrap:'wrap' }}>
            <button onClick={exportCSVLocal} style={{ padding:'8px 12px', background:'#0ea5e9', color:'#fff', borderRadius:6, border:'none', cursor:'pointer' }}>Export Leaderboard (CSV)</button>
            <button onClick={clearLeaderboardHandler} style={{ padding:'8px 12px', background:'#f59e0b', color:'#fff', borderRadius:6, border:'none', cursor:'pointer' }}>Clear Leaderboard</button>
            <button onClick={allowRetake} title="Clears 'quizTaken' flag in this browser" style={{ padding:'8px 12px', background:'#10b981', color:'#fff', borderRadius:6, border:'none', cursor:'pointer' }}>Allow Retake (this browser)</button>
          </div>
        </div>

        <div style={{ borderTop:'1px dashed #e6edf3', paddingTop:12, marginTop:8 }}>
          <h3 style={{ marginTop:0 }}>Schedule Quiz (Automation)</h3>
          <div style={{ display:'flex', gap:12, flexWrap:'wrap', alignItems:'center' }}>
            <label style={{ display:'flex', flexDirection:'column' }}>Start (local):
              <input type="datetime-local" value={startInput} onChange={(e)=>setStartInput(e.target.value)} style={{ padding:8, marginTop:6 }} />
            </label>
            <label style={{ display:'flex', flexDirection:'column' }}>End (local):
              <input type="datetime-local" value={endInput} onChange={(e)=>setEndInput(e.target.value)} style={{ padding:8, marginTop:6 }} />
            </label>
            <label style={{ display:'flex', alignItems:'center', gap:8 }}>
              <input type="checkbox" checked={autoEnabled} onChange={(e)=>setAutoEnabled(e.target.checked)} />
              <span>Enable automation (activate quiz between start and end)</span>
            </label>
            <div style={{ marginLeft:'auto' }}>
              <button onClick={saveSchedule} style={{ padding:'8px 12px', background:'#0ea5e9', color:'#fff', borderRadius:6, border:'none', cursor:'pointer' }}>Save Schedule</button>
            </div>
          </div>
        </div>

        <div style={{ marginTop:18 }}>
          <h3>Participants by Unit</h3>
          <div style={{ overflowX:'auto', marginTop:8 }}>
            <table style={{ width:'100%', borderCollapse:'collapse', minWidth:420 }}>
              <thead>
                <tr style={{ background:'#f3f4f6' }}>
                  <th style={{ padding:8, border:'1px solid #e6edf3', textAlign:'left' }}>S.No</th>
                  <th style={{ padding:8, border:'1px solid #e6edf3', textAlign:'left' }}>Unit</th>
                  <th style={{ padding:8, border:'1px solid #e6edf3', textAlign:'right' }}>Participants</th>
                  <th style={{ padding:8, border:'1px solid #e6edf3', textAlign:'right' }}>Percentage</th>
                </tr>
              </thead>
              <tbody>
                {unitLabels.length===0? (
                  <tr><td colSpan="4" style={{ textAlign:'center', padding:16 }}>No participants yet</td></tr>
                ): unitLabels.map((u,i)=>{
                  const count=unitCounts[u]||0; const pct= total===0?0: (count/total*100);
                  return (
                    <tr key={u}>
                      <td style={{ padding:8, border:'1px solid #eef2f7' }}>{i+1}</td>
                      <td style={{ padding:8, border:'1px solid #eef2f7' }}>{u}</td>
                      <td style={{ padding:8, border:'1px solid #eef2f7', textAlign:'right' }}>{count}</td>
                      <td style={{ padding:8, border:'1px solid #eef2f7', textAlign:'right' }}>{pct.toFixed(1)}%</td>
                    </tr>
                  );
                })}
                {unitLabels.length>0 && (
                  <tr style={{ fontWeight:700, background:'#f9fafb' }}>
                    <td style={{ padding:8, border:'1px solid #eef2f7' }} colSpan={2}>Total</td>
                    <td style={{ padding:8, border:'1px solid #eef2f7', textAlign:'right' }}>{total}</td>
                    <td style={{ padding:8, border:'1px solid #eef2f7', textAlign:'right' }}>100%</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div style={{ marginTop:18 }}>
          <h3>Detailed Leaderboard</h3>
          <Leaderboard results={safeR} />
        </div>

        <button onClick={onLogout} style={{ marginTop:12, padding:'8px 12px', background:'#6b7280', color:'#fff', borderRadius:6, border:'none', cursor:'pointer' }}>Logout</button>
      </div>
    </div>
  );
}

/* ---------------- Admin Login (Firebase Auth) ---------------- */
function AdminGate({ onUnlock }){
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await loginAdmin(email, password);
      onUnlock();
    } catch (err) {
      console.error("Admin login error:", err);
      alert("Invalid email or password.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth:400, margin:'60px auto', padding:24, borderRadius:8, border:'1px solid #e5e7eb', background:'#fff', width:'100%', boxSizing:'border-box' }}>
      <h2 style={{ marginTop:0 }}>Admin Login</h2>
      <input 
        type="email" 
        placeholder="Admin Email" 
        value={email} 
        onChange={(e)=>setEmail(e.target.value)} 
        required
        style={{ width:'100%', padding:10, marginBottom:12, boxSizing:'border-box' }} 
      />
      <input 
        type="password" 
        placeholder="Password" 
        value={password} 
        onChange={(e)=>setPassword(e.target.value)} 
        required
        style={{ width:'100%', padding:10, marginBottom:12, boxSizing:'border-box' }} 
      />
      <button 
        type="submit" 
        disabled={loading}
        style={{ width:'100%', padding:10, background: loading ? '#93c5fd' : '#2563eb', color:'#fff', border:'none', borderRadius:6, cursor: loading ? 'not-allowed' : 'pointer' }}
      >
        {loading ? "Authenticating..." : "Login"}
      </button>
    </form>
  );
}

